// ── helper to build a CryptoAsset row quickly ─────
const mk = (
  id:string, sym:string, name:string, nameFa:string, color:string,
  price:number, irt:number, ch:number, vol:number, cap:number, rank:number
): CryptoAsset => ({
  id, symbol:sym, name, nameFa, logoColor:color,
  price, priceIrt:irt, change24h:ch,
  volume24h:vol, marketCap:cap,
  high24h:price*(1+Math.abs(ch)*0.01*1.5),
  low24h:price*(1-Math.abs(ch)*0.01*1.5),
  rank,
});

